<!DOCTYPE html>
<html lang="pt-BR">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Sistema de Agendamento</title>
  <link rel="stylesheet" href="styles.css">
</head>
<body>
  <div id="app">
    <!-- Tela de login/registro -->
    <div id="auth-screen" class="screen">
      <div class="auth-container">
        <h1>Sistema de Agendamento</h1>

        <div class="tabs">
          <button class="tab active" data-tab="login">Entrar</button>
          <button class="tab" data-tab="registro">Registrar</button>
        </div>

        <form id="login-form" class="auth-form">
          <h2>Entrar</h2>
          <div class="form-group">
            <label>Email</label>
            <input type="email" name="email" required>
          </div>
          <div class="form-group">
            <label>Senha</label>
            <input type="password" name="senha" required>
          </div>
          <button type="submit" class="btn btn-primary">Entrar</button>
          <div class="info-admin">
            <small>Administrador padrão: admin@sistema.com / admin123</small>
          </div>
        </form>

        <form id="registro-form" class="auth-form" style="display: none;">
          <h2>Criar Conta</h2>
          <div class="form-group">
            <label>Nome</label>
            <input type="text" name="nome" required>
          </div>
          <div class="form-group">
            <label>Email</label>
            <input type="email" name="email" required>
          </div>
          <div class="form-group">
            <label>Senha</label>
            <input type="password" name="senha" required minlength="6">
          </div>
          <button type="submit" class="btn btn-primary">Registrar</button>
        </form>

        <div id="auth-erro" class="erro-msg"></div>
      </div>
    </div>

    <!-- Tela principal do cliente -->
    <div id="cliente-screen" class="screen" style="display: none;">
      <header class="header">
        <h1>Meus Agendamentos</h1>
        <div class="user-info">
          <span id="user-nome"></span>
          <button id="logout-btn" class="btn btn-secondary">Sair</button>
        </div>
      </header>

      <div class="container">
        <div class="tabs">
          <button class="tab active" data-tab="novo-agendamento">Novo Agendamento</button>
          <button class="tab" data-tab="meus-agendamentos">Meus Agendamentos</button>
        </div>

        <!-- Novo agendamento -->
        <div id="novo-agendamento" class="tab-content">
          <form id="form-novo-agendamento">
            <div class="form-group">
              <label>Serviço</label>
              <select name="servico_id" id="select-servico" required>
                <option value="">Selecione um serviço</option>
              </select>
              <div id="info-servico" class="info-box"></div>
            </div>

            <div class="form-group">
              <label>Data</label>
              <input type="date" name="data" id="input-data" required>
            </div>

            <div class="form-group">
              <label>Horário</label>
              <select name="hora" id="select-horario" required>
                <option value="">Selecione uma data primeiro</option>
              </select>
            </div>

            <div class="form-group">
              <label>Observações (opcional)</label>
              <textarea name="observacoes" rows="3"></textarea>
            </div>

            <button type="submit" class="btn btn-primary">Agendar</button>
          </form>
        </div>

        <!-- Meus agendamentos -->
        <div id="meus-agendamentos" class="tab-content" style="display: none;">
          <div id="lista-agendamentos-cliente"></div>
        </div>
      </div>
    </div>

    <!-- Tela principal do admin -->
    <div id="admin-screen" class="screen" style="display: none;">
      <header class="header">
        <h1>Painel Administrativo</h1>
        <div class="user-info">
          <span id="admin-nome"></span>
          <button id="admin-logout-btn" class="btn btn-secondary">Sair</button>
        </div>
      </header>

      <div class="container">
        <div class="tabs">
          <button class="tab active" data-tab="admin-agendamentos">Agendamentos</button>
          <button class="tab" data-tab="admin-servicos">Serviços</button>
          <button class="tab" data-tab="admin-horarios">Horários</button>
        </div>

        <!-- Agendamentos -->
        <div id="admin-agendamentos" class="tab-content">
          <h2>Todos os Agendamentos</h2>
          <div id="lista-agendamentos-admin"></div>
        </div>

        <!-- Serviços -->
        <div id="admin-servicos" class="tab-content" style="display: none;">
          <div class="section-header">
            <h2>Serviços</h2>
            <button id="btn-novo-servico" class="btn btn-primary">Novo Serviço</button>
          </div>

          <div id="form-servico-container" style="display: none;">
            <form id="form-servico">
              <input type="hidden" name="id">
              <div class="form-group">
                <label>Nome</label>
                <input type="text" name="nome" required>
              </div>
              <div class="form-group">
                <label>Descrição</label>
                <textarea name="descricao" rows="3"></textarea>
              </div>
              <div class="form-row">
                <div class="form-group">
                  <label>Duração (minutos)</label>
                  <input type="number" name="duracao" required min="15" step="15">
                </div>
                <div class="form-group">
                  <label>Preço (R$)</label>
                  <input type="number" name="preco" required min="0" step="0.01">
                </div>
              </div>
              <div class="form-actions">
                <button type="submit" class="btn btn-primary">Salvar</button>
                <button type="button" id="btn-cancelar-servico" class="btn btn-secondary">Cancelar</button>
              </div>
            </form>
          </div>

          <div id="lista-servicos"></div>
        </div>

        <!-- Horários -->
        <div id="admin-horarios" class="tab-content" style="display: none;">
          <div class="section-header">
            <h2>Horários Disponíveis</h2>
            <button id="btn-novo-horario" class="btn btn-primary">Novo Horário</button>
          </div>

          <div id="form-horario-container" style="display: none;">
            <form id="form-horario">
              <div class="form-group">
                <label>Dia da Semana</label>
                <select name="dia_semana" required>
                  <option value="0">Domingo</option>
                  <option value="1">Segunda-feira</option>
                  <option value="2">Terça-feira</option>
                  <option value="3">Quarta-feira</option>
                  <option value="4">Quinta-feira</option>
                  <option value="5">Sexta-feira</option>
                  <option value="6">Sábado</option>
                </select>
              </div>
              <div class="form-row">
                <div class="form-group">
                  <label>Hora Início</label>
                  <input type="time" name="hora_inicio" required>
                </div>
                <div class="form-group">
                  <label>Hora Fim</label>
                  <input type="time" name="hora_fim" required>
                </div>
              </div>
              <div class="form-actions">
                <button type="submit" class="btn btn-primary">Salvar</button>
                <button type="button" id="btn-cancelar-horario" class="btn btn-secondary">Cancelar</button>
              </div>
            </form>
          </div>

          <div id="lista-horarios"></div>
        </div>
      </div>
    </div>
  </div>

  <div id="modal" class="modal">
    <div class="modal-content">
      <p id="modal-message"></p>
      <button id="modal-ok" class="btn btn-primary">OK</button>
    </div>
  </div>

  <script src="app.js"></script>
</body>
</html>

=== public/styles.css ===
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
